params.python_function:
ind = {{ vars.indicator | default('', true) | string | tojson }}
norm = ''
try:
    norm = str(ind).strip()
except Exception:
    norm = ''
low = norm.lower()
t = 'unknown'
mdetype = ''
if low.startswith('http://') or low.startswith('https://'):
    t = 'url'
    mdetype = 'Url'
else:
    hexchars = True
    for ch in low:
        if ch not in '0123456789abcdef':
            hexchars = False
            break
    if hexchars and len(low) == 64:
        t = 'sha256'
        mdetype = 'FileSha256'
    elif hexchars and len(low) == 40:
        t = 'sha1'
        mdetype = 'FileSha1'
    elif hexchars and len(low) == 32:
        t = 'md5'
        mdetype = 'FileMd5'
    else:
        isip = True
        parts = norm.split('.')
        if len(parts) != 4:
            isip = False
        p = 0
        while p < len(parts):
            try:
                v = int(parts[p])
            except Exception:
                isip = False
                break
            if v < 0 or v > 255:
                isip = False
                break
            p = p + 1
        if isip:
            t = 'ip'
            mdetype = 'IpAddress'
        elif ':' in norm:
            t = 'ipv6'
            mdetype = 'IpAddress'
        elif '.' in norm and ' ' not in norm:
            t = 'domain'
            mdetype = 'DomainName'
print({'normalized': norm, 'indicator_type': t, 'defender_type': mdetype})

raw_score = {{ (vars.steps.Search_FortiGuard.data | default([], true) | first | default({}, true)).risk_score | default('', true) | string | tojson }}
risk_level = {{ ((vars.steps.Search_FortiGuard.data | default([], true) | first | default({}, true)).risk_level or {}).itemValue | default('', true) | string | tojson }}
confidence = {{ ((vars.steps.Search_FortiGuard.data | default([], true) | first | default({}, true)).confidence or {}).itemValue | default('', true) | string | tojson }}
category = {{ (vars.steps.Search_FortiGuard.data | default([], true) | first | default({}, true)).av_cate | default('', true) | string | tojson }}
malicious_at = {{ vars.malicious_at | default('80', true) | int }}
suspicious_at = {{ vars.suspicious_at | default('50', true) | int }}
verdict = 'unknown'
if raw_score != '':
    try:
        score = int(raw_score)
    except Exception:
        score = -1
    if score >= malicious_at:
        verdict = 'malicious'
    elif score >= suspicious_at:
        verdict = 'suspicious'
    else:
        verdict = 'clean'
print({'verdict': verdict, 'risk_score': raw_score, 'risk_level': risk_level,
       'confidence': confidence, 'category': category})

wanted = {{ vars.input.params.indicator | default('', true) | string | lower | tojson }}
ids = {{ vars.steps.Find_Matching_TL_Requests.data.approval_requests | default([], true) | map(attribute='approvalRequestId') | map('default', '') | map('string') | list | tojson }}
hashes = {{ vars.steps.Find_Matching_TL_Requests.data.approval_requests | default([], true) | map(attribute='hash') | map('default', '') | map('string') | list | tojson }}
actions = {{ vars.steps.Find_Matching_TL_Requests.data.approval_requests | default([], true) | map(attribute='actionDate') | map('default', '') | map('string') | list | tojson }}
matched = []
n = len(ids)
if len(hashes) == n and len(actions) == n:
    i = 0
    while i < n:
        if hashes[i] != '' and actions[i] == '' and ids[i] != '':
            if hashes[i].strip().lower() == wanted.strip().lower():
                matched.append(ids[i])
        i = i + 1
print({'request_ids': ','.join(matched), 'count': len(matched)})

