ids = {{ vars.steps.List_Pending_Requests.data.approval_requests | default([], true) | map(attribute='approvalRequestId') | map('default', '') | map('string') | list | tojson }}
hashes = {{ vars.steps.List_Pending_Requests.data.approval_requests | default([], true) | map(attribute='hash') | map('default', '') | map('string') | list | tojson }}
paths = {{ vars.steps.List_Pending_Requests.data.approval_requests | default([], true) | map(attribute='path') | map('default', '') | map('string') | list | tojson }}
hostnames = {{ vars.steps.List_Pending_Requests.data.approval_requests | default([], true) | map(attribute='hostname') | map('default', '') | map('string') | list | tojson }}
usernames = {{ vars.steps.List_Pending_Requests.data.approval_requests | default([], true) | map(attribute='username') | map('default', '') | map('string') | list | tojson }}
reasons = {{ vars.steps.List_Pending_Requests.data.approval_requests | default([], true) | map(attribute='requestorReason') | map('default', '') | map('string') | list | tojson }}
requested_ats = {{ vars.steps.List_Pending_Requests.data.approval_requests | default([], true) | map(attribute='dateTime') | map('default', '') | map('string') | list | tojson }}
actions = {{ vars.steps.List_Pending_Requests.data.approval_requests | default([], true) | map(attribute='actionDate') | map('default', '') | map('string') | list | tojson }}
picked = {}
pending = 0
n = len(ids)
if len(hashes) == n and len(actions) == n and len(paths) == n and len(hostnames) == n and len(usernames) == n and len(reasons) == n and len(requested_ats) == n:
    i = 0
    while i < n:
        if actions[i] == '':
            pending = pending + 1
            if not picked and hashes[i] != '':
                picked = {'request_id': ids[i], 'file_hash': hashes[i],
                          'path': paths[i], 'hostname': hostnames[i],
                          'username': usernames[i], 'requestor_reason': reasons[i],
                          'requested_at': requested_ats[i]}
        i = i + 1
print({'picked': picked, 'pending_count': pending})

